import { useParams, useNavigate } from 'react-router';
import {
  Card, Tag, Space, Typography, Timeline, Button, Form, Input, App as AntApp, Divider, Spin,
} from 'antd';
import { ArrowLeftOutlined } from '@ant-design/icons';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api, getErrorMessage } from '../../lib/api';
import { RequestStatus, CommentVisibility } from '@phison/types';
import { formatDateTime } from '../../lib/formatters';

const { Title, Text, Paragraph } = Typography;

interface RequestDetail {
  id: string;
  subject: string;
  description: string;
  category: string;
  status: string;
  createdAt: string;
  history: Array<{ id: string; toStatus: string; comment: string | null; timestamp: string }>;
  comments: Array<{ id: string; body: string; authorId: string; createdAt: string }>;
}

const STATUS_COLORS: Record<string, string> = {
  submitted: 'orange', acknowledged: 'blue', in_progress: 'cyan',
  resolved: 'green', closed: 'default', rejected: 'red',
};

export default function ResidentRequestDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { message } = AntApp.useApp();
  const qc = useQueryClient();
  const [form] = Form.useForm();

  const { data: request, isLoading } = useQuery({
    queryKey: ['request', id],
    queryFn: () => api.get<RequestDetail>(`/requests/${id}`).then(r => r.data),
    enabled: !!id,
  });

  const commentMutation = useMutation({
    mutationFn: (v: { body: string }) =>
      api.post(`/requests/${id}/comments`, { ...v, visibility: CommentVisibility.Public }),
    onSuccess: () => {
      message.success('Comment added');
      qc.invalidateQueries({ queryKey: ['request', id] });
      form.resetFields();
    },
    onError: (e) => message.error(getErrorMessage(e)),
  });

  if (isLoading) return <Spin />;
  if (!request) return null;

  const canComment = request.status !== RequestStatus.Closed && request.status !== RequestStatus.Rejected;

  return (
    <Space direction="vertical" size={16} style={{ width: '100%' }}>
      <Space>
        <Button icon={<ArrowLeftOutlined />} onClick={() => navigate(-1)}>Back</Button>
        <Title level={4} style={{ margin: 0 }}>{request.subject}</Title>
        <Tag color={STATUS_COLORS[request.status]}>{request.status.replace(/_/g, ' ')}</Tag>
      </Space>

      <Card>
        <Paragraph>{request.description}</Paragraph>
        <Text type="secondary">{request.category} · {formatDateTime(request.createdAt)}</Text>
      </Card>

      <Card title="History">
        <Timeline
          items={request.history.map(h => ({
            children: (
              <Space direction="vertical" size={2}>
                <Tag color={STATUS_COLORS[h.toStatus]}>{h.toStatus.replace(/_/g, ' ')}</Tag>
                {h.comment && <Text>{h.comment}</Text>}
                <Text type="secondary" style={{ fontSize: 12 }}>{formatDateTime(h.timestamp)}</Text>
              </Space>
            ),
          }))}
        />
      </Card>

      <Card title="Comments">
        <Space direction="vertical" style={{ width: '100%' }}>
          {request.comments.map(c => (
            <Card key={c.id} size="small" styles={{ body: { padding: '8px 12px' } }}>
              <Paragraph style={{ margin: 0 }}>{c.body}</Paragraph>
              <Text type="secondary" style={{ fontSize: 11 }}>{formatDateTime(c.createdAt)}</Text>
            </Card>
          ))}

          {canComment && (
            <>
              <Divider style={{ margin: '8px 0' }} />
              <Form form={form} onFinish={v => commentMutation.mutate(v)} layout="vertical">
                <Form.Item name="body" rules={[{ required: true }]}>
                  <Input.TextArea rows={3} placeholder="Add a comment…" />
                </Form.Item>
                <Button type="primary" htmlType="submit" loading={commentMutation.isPending}>
                  Send
                </Button>
              </Form>
            </>
          )}
        </Space>
      </Card>
    </Space>
  );
}
